package com.schwab.urlshortener.agentic.model;

/**
 * What actually produced one artifact. Kept distinct from
 * {@link ExecutionMode} because an LLM-mode run still contains one
 * deterministic artifact (the REVIEW quality gate), and that artifact must
 * not be labeled as either "the model wrote this" or "demo stand-in" —
 * it's deterministic by design in every mode.
 */
public enum ArtifactSource {
    /** Generated by a Claude model call (LLM mode). */
    LLM,
    /** Rule-based stand-in for an LLM stage (DETERMINISTIC_DEMO mode). */
    DETERMINISTIC_DEMO,
    /** The deterministic quality gate — never model-generated, in any mode. */
    DETERMINISTIC_GUARDRAIL
}
